<?php
namespace App\Controller\Admin;
use App\Entity\Unit; use App\Enum\Dimension; use EasyCorp\Bundle\EasyAdminBundle\Config\Crud; use EasyCorp\Bundle\EasyAdminBundle\Controller\AbstractCrudController; use EasyCorp\Bundle\EasyAdminBundle\Field\BooleanField; use EasyCorp\Bundle\EasyAdminBundle\Field\ChoiceField; use EasyCorp\Bundle\EasyAdminBundle\Field\IdField; use EasyCorp\Bundle\EasyAdminBundle\Field\NumberField; use EasyCorp\Bundle\EasyAdminBundle\Field\TextField;
class UnitCrudController extends AbstractCrudController { public static function getEntityFqcn(): string{return Unit::class;} public function configureCrud(Crud $crud): Crud{return $crud->setEntityLabelInSingular('Unidad')->setEntityLabelInPlural('Unidades');} public function configureFields(string $p): iterable { yield IdField::new('id')->onlyOnIndex(); yield TextField::new('name','Nombre'); yield TextField::new('code','Código'); yield TextField::new('symbol','Símbolo'); yield ChoiceField::new('dimension','Dimensión')->setChoices(array_combine(array_map(fn($d)=>$d->label(),Dimension::cases()),Dimension::cases())); yield NumberField::new('toBaseFactor','Factor a unidad base')->setHelp('g, ml y unidad tienen factor 1; kg y litro, 1000; docena, 12.'); yield BooleanField::new('active','Activa'); } }
